void OnStart() {
    m_body = Find<Rigidbody2DComponent>();
    ENGINE_LOG_INFO(Channels::kGame, "{} is ready", name);
}

void OnUpdate() {
    if (InputMap::IsPressed("Jump")) {
        m_jumpQueued = true;   // consumed in the next fixed step
    }
}

void OnCollisionEnter(const eng::Collision2D& hit) {
    if (hit.normal.y > 0.7f) {
        m_grounded = true;         // landed on top of something
    }
}

void OnTriggerEnter(Collider2D other) {
    eng::Entity* owner = other->Owner();
    if (owner != nullptr && owner->HasTag("Pickup")) {
        Destroy(owner->Id());
    }
}

void OnExpose(eng::ScriptFields& fields) {
    fields.Var("range", range, "how far it can shoot, in pixels");
    fields.Range("spread", spread, 0.0f, 1.0f, "0 is dead straight");
}
